function target(serviceName = "conformance-svc"): TracingTarget & { exporter: MemorySpanExporter } {
  const exporter = new MemorySpanExporter();
  const handle = initTracingWith({ serviceName, sampler: "always_on" }, () => exporter);
  return { exporter, handle, query: new MemoryTraceQueryClient(exporter) };
}

function span(over: Partial<Span>): Span {
  return {
    traceId: "1".repeat(32),
    spanId: "1".repeat(16),
    name: "op",
    kind: "server",
    serviceName: "api",
    startMicros: 1_000_000,
    endMicros: 1_500_000,
    durationMicros: 500_000,
    status: { code: "unset" },
    attributes: {},
    events: [],
    links: [],
    ...over,
  };
}

