describe("tracing ops", () => {
  const ctx = {} as OpContext;

  it("creates span trees with events, errors and kinds", async () => {
    const t = target("ops");
    const traceId = createSpanTree(t.handle.tracer("x"), {
      name: "root",
      kind: "server",
      events: ["a", { name: "b", attributes: { n: 1 } }, { name: "c" }],
      children: [{ name: "child", error: "bad" }],
    });
    await t.handle.forceFlush();
    const trace = (await t.query!.getTrace(traceId))!;
    expect(trace.spans.map((s) => s.name).sort()).toEqual(["child", "root"]);
    const root = trace.spans.find((s) => s.name === "root")!;
    expect(root.events.map((e) => e.name)).toEqual(["a", "b", "c"]);
    expect(trace.spans.find((s) => s.name === "child")?.status).toEqual({
      code: "error",
      message: "bad",
    });
    expect(() =>
      createSpanTree(t.handle.tracer("x"), { name: "r", children: [{} as never] }),
    ).toThrow(ValidationError);
    expect(() => tracingOps.ops.span!(t, { name: 1 }, ctx)).toThrow(ValidationError);
    expect(tracingOps.variables!(t)).toEqual({ serviceName: "ops" });
    expect(tracingOps.variables!({ ...t, serviceName: "override" })).toEqual({
      serviceName: "override",
    });
    await tracingOps.dispose!(t, ctx);
  });

  it("getTraceUntil returns the shortfall, validates args and needs a query client", async () => {
    const t = target();
    const id = String(tracingOps.ops.span!(t, { name: "lonely" }, ctx));
    await tracingOps.ops.flush!(t, { timeoutMs: 1000 }, ctx);
    const short = (await tracingOps.ops.getTraceUntil!(
      t,
      { traceId: id, minSpans: 3, timeoutMs: 20, intervalMs: 5 },
      ctx,
    )) as Trace;
    expect(short.spans).toHaveLength(1);
    expect(
      ((await tracingOps.ops.getTraceUntil!(t, { traceId: id }, ctx)) as Trace).spans,
    ).toHaveLength(1);
    await expect(
      Promise.resolve(
        tracingOps.ops.getTraceUntil!(
          t,
          { traceId: "2".repeat(32), timeoutMs: 10, intervalMs: 5 },
          ctx,
        ),
      ),
    ).rejects.toBeInstanceOf(TimeoutError);
    await expect(Promise.resolve(tracingOps.ops.getTraceUntil!(t, {}, ctx))).rejects.toBeInstanceOf(
      ValidationError,
    );
    const noQuery = { ...t, query: null };
    await expect(
      Promise.resolve(tracingOps.ops.getTraceUntil!(noQuery, { traceId: id }, ctx)),
    ).rejects.toBeInstanceOf(UnsupportedError);
    expect(() => tracingOps.ops.listServices!(noQuery, {}, ctx)).toThrow(UnsupportedError);
    // listServices polls until the step expectation passes (late service lists)
    let calls = 0;
    const late = {
      ...t,
      query: { listServices: () => Promise.resolve(++calls < 3 ? [] : ["late-svc"]) },
    } as unknown as TracingTarget;
    const stepCtx = {
      step: { op: "listServices", expect: { contains: "${svc}" } },
      substitute: <T>(v: T): T => JSON.parse(JSON.stringify(v).replace("${svc}", "late-svc")) as T,
    } as unknown as OpContext;
    expect(await tracingOps.ops.listServices!(late, { intervalMs: 1 }, stepCtx)).toEqual([
      "late-svc",
    ]);
    expect(calls).toBe(3);
    await tracingOps.ops.flush!(t, {}, ctx);
    await tracingOps.dispose!(t, ctx);
  });
});

describe("MemorySpanExporter", () => {
  it("fails on demand and after shutdown", async () => {
    const e = new MemorySpanExporter();
    const results: number[] = [];
    e.failNext().export([], (r) => results.push(r.code));
    e.export([], (r) => results.push(r.code));
    await e.forceFlush();
    await e.shutdown();
    e.export([], (r) => results.push(r.code));
    expect(results).toEqual([1, 0, 1]);
    expect(e.shutdownCalls).toBe(1);
  });
});

