describe("waitForTrace / BaseTraceQueryClient", () => {
  class Flaky extends BaseTraceQueryClient {
    calls = 0;
    getTrace(traceId: string): Promise<Trace | null> {
      this.calls += 1;
      if (this.calls === 1) return Promise.reject(new NotFoundError("not yet"));
      if (this.calls === 2) return Promise.resolve(null);
      return Promise.resolve({ traceId, spans: [span({ traceId })] });
    }
    searchTraces(): Promise<TraceSummary[]> {
      return Promise.resolve([]);
    }
    listServices(): Promise<string[]> {
      return Promise.resolve([]);
    }
    listOperations(): Promise<string[]> {
      return Promise.resolve([]);
    }
  }

  it("polls through NotFound and null until enough spans", async () => {
    const f = new Flaky();
    const t = await f.waitForTrace("ABC", { intervalMs: 1 });
    expect(t.traceId).toBe("abc".padStart(32, "0"));
    expect(f.calls).toBe(3);
    await expect(f.getDependencies()).rejects.toBeInstanceOf(UnsupportedError);
    await expect(
      waitForTrace(new Flaky(), "abc", { minSpans: 2, intervalMs: 1, timeoutMs: 20 }),
    ).rejects.toBeInstanceOf(TimeoutError);
    const controller = new AbortController();
    controller.abort();
    await expect(
      waitForTrace(new Flaky(), "abc", { signal: controller.signal }),
    ).rejects.toMatchObject({ code: "CANCELLED" });
    expect((await waitForTrace(new Flaky(), "abc", { intervalMs: 1 })).spans).toHaveLength(1);
    await expect(waitForTrace(new Flaky(), "nothex")).rejects.toBeInstanceOf(ValidationError);
    const native = await waitForTrace(new Flaky(), "Seg.1.2", {
      intervalMs: 1,
      normalizeId: (id) => id,
    });
    expect(native.traceId).toBe("Seg.1.2");
  });
});
